  box-shadow:
    0 22px 40px color-mix(in srgb, var(--ink) 20%, transparent),
    0 1px 0 color-mix(in srgb, #fff 12%, transparent) inset;
}

.profile-community-card:focus-visible {
  outline: 2px solid var(--picom-aqua);
  outline-offset: 3px;
}

.profile-community-card__hero {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #1a2428;
}

.profile-community-card__hero img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transform: scale(1.02);
}

.profile-community-card__monogram {
  font-size: clamp(42px, 18vw, 72px);
  font-weight: 900;
  letter-spacing: -0.04em;
  color: color-mix(in srgb, #fff 88%, transparent);
  text-shadow: 0 10px 30px color-mix(in srgb, #000 35%, transparent);
  user-select: none;
}

.profile-community-card__body {
  position: relative;
  z-index: 1;
  align-self: end;
  display: grid;
  gap: 10px;
  padding: 22px 18px 18px;
  background:
    linear-gradient(
      180deg,
      transparent 0%,
      color-mix(in srgb, #0b1012 42%, transparent) 28%,
      color-mix(in srgb, #0b1012 88%, transparent) 72%,
      #0b1012 100%
    );
  backdrop-filter: blur(0.5px);
}

.profile-community-card__title {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #fff;
  font-size: 22px;
  font-weight: 850;
  letter-spacing: -0.03em;
  line-height: 1.15;
}

.profile-community-card__description {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  min-height: 3.6em;
  color: color-mix(in srgb, #fff 78%, transparent);
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.45;
}

.profile-community-card__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profile-community-card__chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  background: color-mix(in srgb, #fff 14%, transparent);
  color: color-mix(in srgb, #fff 92%, transparent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.profile-community-card__cta {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 44px;
  margin-top: 4px;
  border-radius: 999px;
  background: #fff;
  color: #1a1f24;
  font-size: 14px;
  font-weight: 850;
  letter-spacing: -0.01em;
  box-shadow: 0 8px 18px color-mix(in srgb, #000 28%, transparent);
  transition: background 140ms ease, transform 140ms ease;
}

.profile-community-card:hover .profile-community-card__cta {
  background: #f4f6f7;
}

.profile-community-card:active .profile-community-card__cta {
  transform: translateY(1px);
}

.profile-empty-state {
  min-height: 120px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 6px;
  padding: 24px 20px;
  border: 1px dashed color-mix(in srgb, var(--border) 88%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--surface-soft) 50%, var(--surface));
  color: var(--text-muted);
  text-align: center;
}

.profile-empty-state strong {
  color: var(--text-primary);
  font-size: 14px;
}

.profile-empty-state span {
  max-width: 420px;
  font-size: 12px;
  line-height: 1.45;
}

.profile-empty-inline {
  grid-column: 1 / -1;
  padding: 12px 14px;
  border: 1px dashed color-mix(in srgb, var(--border) 88%, transparent);
  border-radius: 12px;
  color: var(--text-muted);
  font-size: 12px;
}

/* Compatibility aliases for ProfileAudioSections */
.profile-section {
  padding: 18px 20px;
  border: 1px solid color-mix(in srgb, var(--border) 86%, transparent);
  border-radius: 22px;
  background: color-mix(in srgb, var(--surface) 94%, transparent);
  box-shadow: var(--shadow-soft);
}

.profile-section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.profile-section-header h2 {
  margin: 4px 0 0;
  font-size: 18px;
  font-weight: 850;
}

.profile-empty-panel {
  min-height: 96px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 6px;
  padding: 20px;
  border: 1px dashed color-mix(in srgb, var(--border) 88%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--surface-soft) 50%, var(--surface));
  color: var(--text-muted);
  text-align: center;
}

.profile-source-state.error .profile-source-state-icon {
  background: color-mix(in srgb, var(--danger) 10%, var(--surface));
  color: var(--danger);
}

.profile-source-state {
  min-height: 150px;
  display: flex;
  align-items: center;
  gap: 16px;
}

.profile-source-state-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 14px;
  background: var(--accent-soft);
  color: var(--accent);
}

.profile-source-state.is-error .profile-source-state-icon {
  background: color-mix(in srgb, var(--danger) 10%, var(--surface));
  color: var(--danger);
}

.profile-source-state h2,
.profile-source-state p {
  margin: 0;
}

.profile-source-state p {
  color: var(--text-muted);
  font-size: 13px;
  line-height: 1.45;
}

.profile-loading-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.profile-loading-grid i {
  height: 120px;
  border-radius: 18px;
  background: linear-gradient(100deg, var(--surface-soft) 20%, var(--surface-hover) 45%, var(--surface-soft) 70%);
  background-size: 220% 100%;
  animation: profile-loading-shimmer 1.4s ease infinite;
}

.profile-name-with-verification {
  justify-content: center;
}

.verified-profile-avatar {
  margin: 0 auto;
}

.profile-edit-camera-button {
  position: absolute;
  z-index: 5;
  right: -5px;
  bottom: 5px;
  display: grid;
  width: 36px;
  height: 36px;
  padding: 0;
  place-items: center;
  border: 3px solid var(--surface-elevated, var(--app-surface));
  border-radius: 50%;
  background: var(--verified-blue);
  color: #fff;
  box-shadow: 0 7px 18px color-mix(in srgb, var(--verified-blue) 34%, transparent);
  cursor: pointer;
}

.profile-edit-camera-button:hover {
  background: color-mix(in srgb, var(--verified-blue) 84%, white);
  transform: translateY(-1px);
}

.profile-edit-camera-button:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

/* Audio sections (ProfileAudioSections) */
.profile-audio-sections { display: grid; gap: 14px; }
.profile-audio-sections > .audio-mini-player { position: sticky; top: 0; z-index: 4; }
.profile-audio-card-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.profile-radio-card { min-width: 0; display: grid; grid-template-columns: 108px minmax(0, 1fr); overflow: hidden; border: 1px solid var(--border); border-radius: 16px; background: var(--surface-soft); }
.profile-audio-cover { position: relative; min-height: 142px; display: grid; place-items: center; overflow: hidden; background: var(--accent-soft); color: var(--accent); }
.profile-audio-cover img { width: 100%; height: 100%; display: block; object-fit: cover; }
.profile-audio-cover > span { position: absolute; left: 8px; top: 8px; padding: 5px 7px; border-radius: 999px; background: color-mix(in srgb, var(--surface) 82%, transparent); color: var(--text-primary); font-size: 8px; font-weight: 900; text-transform: uppercase; }
.profile-audio-cover > span.live { background: color-mix(in srgb, var(--danger) 82%, transparent); color: var(--text-on-accent); }
.profile-radio-card > div:last-child { min-width: 0; display: flex; flex-direction: column; gap: 6px; padding: 11px; }
.profile-radio-card h3, .profile-podcast-list h3 { margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.profile-radio-card button, .profile-podcast-list button { border: 0; background: transparent; color: var(--accent); padding: 0; text-align: left; font-size: 9px; cursor: pointer; }
.profile-radio-card small, .profile-podcast-list small, .profile-podcast-list article > div > span { color: var(--text-muted); font-size: 8px; }
.profile-radio-card footer { display: flex; gap: 5px; margin-top: auto; }
.profile-radio-card footer button { min-height: 29px; display: inline-flex; align-items: center; gap: 5px; padding: 0 8px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); color: var(--text-secondary); font-weight: 800; }
.profile-radio-card footer button.primary, .profile-radio-card footer button.active { background: var(--accent-soft); color: var(--accent); }
.profile-podcast-list { display: grid; gap: 7px; }
.profile-podcast-list > article { min-width: 0; display: grid; grid-template-columns: 54px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 9px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-soft); }
.profile-podcast-cover { width: 54px; height: 54px; display: grid; place-items: center; overflow: hidden; border-radius: 12px; background: var(--accent-soft); color: var(--accent); }
.profile-podcast-cover img { width: 100%; height: 100%; display: block; object-fit: cover; }
.profile-podcast-list article > div:nth-child(2) { min-width: 0; display: grid; gap: 3px; }
.profile-podcast-actions { display: flex; gap: 4px; }
.profile-podcast-actions button { width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid var(--border); border-radius: 10px; background: var(--surface); color: var(--text-muted); }
.profile-podcast-actions button.primary, .profile-podcast-actions button.active { background: var(--accent-soft); color: var(--accent); }
.profile-saved-audio { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
.profile-saved-audio > button { min-width: 0; display: grid; grid-template-columns: 24px minmax(0, 1fr) 16px; align-items: center; gap: 8px; padding: 9px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface-soft); color: var(--text-secondary); text-align: left; cursor: pointer; }
.profile-saved-audio > button > span { min-width: 0; display: grid; gap: 2px; }
.profile-saved-audio strong, .profile-saved-audio small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.profile-saved-audio strong { color: var(--text-primary); font-size: 10px; }
.profile-saved-audio small { color: var(--text-muted); font-size: 8px; }
.profile-audio-privacy-note { padding: 0 4px; color: var(--text-muted); font-size: 9px; }

@keyframes profile-loading-shimmer {
  to { background-position: -220% 0; }
}

@media (max-width: 1320px) {
  .profile-page-shell {
    grid-template-columns: minmax(260px, 288px) minmax(0, 1fr);
  }

  .profile-stats-strip {
    flex-wrap: wrap;
  }

  .profile-stat-item {
    flex: 1 1 calc(50% - 1px);
  }

  .profile-stat-item:nth-child(odd) {
    border-left: 0;
  }

  .profile-stat-item:nth-child(n + 3) {
    border-top: 1px solid color-mix(in srgb, var(--border) 84%, transparent);
  }
}

@media (max-width: 1080px) {
  .profile-page-shell {
    grid-template-columns: minmax(0, 1fr);
    overflow: auto;
  }

  .profile-rail {
    overflow: visible;
  }

  .profile-content {
    overflow: visible;
  }

  .profile-action-secondary {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .profile-action-secondary .profile-btn--icon {
    grid-column: 1 / -1;
    width: 100%;
  }

  .profile-community-list {
    grid-template-columns: minmax(0, 1fr);
  }

  .profile-community-card {
    min-height: 280px;
    aspect-ratio: 4 / 5;
  }

  .profile-community-card__title {
    font-size: 20px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .profile-gallery-tile img,
  .profile-shared-tile img,
  .profile-btn,
  .profile-community-card,
  .profile-community-card__cta,
  .profile-edit-camera-button:hover {
    transition: none;
    transform: none;
  }

  .profile-community-card:hover {
    transform: none;
  }

  .profile-loading-grid i {
    animation: none;
  }
}
